import rsa
from typing import Dict


def generate_rsa_keys(nbits: int) -> Dict[str, str]:
    """Generate a pair of RSA public and private keys with specified bit length.

    Args:
        nbits: The number of bits required to store the modulus n

    Returns:
        A dictionary containing the public and private keys as strings

    Example:
        >>> generate_rsa_keys(2048)
        {'public': '-----BEGIN RSA PUBLIC KEY-----...', 'private': '-----BEGIN RSA PRIVATE KEY-----...'}
    """
    if nbits < 16:
        raise ValueError("Key too small")

    try:
        pub_key, priv_key = rsa.newkeys(nbits)
        return {
            "public": str(pub_key),
            "private": str(priv_key)
        }
    except Exception as e:
        raise ValueError(f"Failed to generate RSA keys: {str(e)}")

import rsa


def load_public_key_pem(keyfile: str) -> str:
    """Loads a PKCS#1.5 PEM-encoded public key file from OpenSSL. keyfile: contents of a PEM-encoded file that contains the public key, from OpenSSL, e.g. '-----BEGIN PUBLIC KEY-----\\nMIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEA...' -> PublicKey object as string."""
    try:
        key_bytes = keyfile.encode('utf-8')
        public_key = rsa.PublicKey.load_pkcs1_openssl_pem(key_bytes)
        return str(public_key)
    except Exception as e:
        raise ValueError(f"Failed to load public key: {str(e)}")

import rsa


def load_public_key_der(keyfile: str) -> str:
    """Loads a PKCS#1 DER-encoded public key file from OpenSSL.

    :param keyfile: contents of a DER-encoded file that contains the public
        key, from OpenSSL.
    :return: a PublicKey object
    """
    try:
        key_bytes = keyfile.encode('latin1') if isinstance(keyfile, str) else keyfile
        public_key = rsa.PublicKey.load_pkcs1_openssl_der(key_bytes)
        return str(public_key)
    except Exception as e:
        raise ValueError(f"Failed to load public key: {str(e)}")

import rsa
from rsa import core, transform, common, key


def find_signature_hash_method(signature: str, pub_key: object) -> str:
    """Returns the hash name detected from the signature.

    If you also want to verify the message, use rsa.verify() instead.
    It also returns the name of the used hash.

    :param signature: the signature block, as created with rsa.sign.
    :param pub_key: the rsa.PublicKey of the person signing the message.
    :returns: the name of the used hash.
    """
    try:
        # Convert signature string to bytes if needed
        if isinstance(signature, str):
            signature_bytes = signature.encode('latin1') if not all(ord(c) < 256 for c in signature) else signature.encode('utf-8')
        else:
            signature_bytes = signature

        # Validate pub_key type
        if not isinstance(pub_key, key.PublicKey):
            raise ValueError("pub_key must be an rsa.PublicKey object")

        # Call the underlying function
        return rsa.find_signature_hash(signature_bytes, pub_key)

    except Exception as e:
        if isinstance(e, ValueError):
            raise e
        raise ValueError(f"Error processing signature: {str(e)}")

from rsa.common import bit_size


def get_integer_bit_size(num: int) -> int:
    """Calculate the number of bits needed to represent an integer. num: Integer value. If num is 0, returns 0. Only the absolute value of the number is considered."""
    try:
        return bit_size(num)
    except TypeError as e:
        raise ValueError(f"Invalid input: {num!r} is not an integer") from e

