from rsa.common import byte_size as _rsa_byte_size


def get_integer_byte_size(number: int) -> int:
    """Calculate the number of bytes required to store an integer. number: An unsigned integer -> The number of bytes required to hold the integer."""
    if not isinstance(number, int) or number < 0:
        raise ValueError("number must be a non-negative integer")

    try:
        return _rsa_byte_size(number)
    except Exception as e:
        raise ValueError(f"failed to calculate byte size for number {number}: {str(e)}") from e

import typing
from rsa.common import extended_gcd


def extended_euclidean_algorithm(a: int, b: int) -> typing.Tuple[int, int, int]:
    """Returns a tuple (r, i, j) such that r = gcd(a, b) = ia + jb. Example: extended_euclidean_algorithm(30, 18) -> (6, -1, 2)"""
    try:
        return extended_gcd(a, b)
    except Exception as e:
        raise ValueError(f"Failed to compute extended GCD: {str(e)}") from e

def encrypt_integer(message: int, ekey: int, n: int) -> int:
    """Encrypts a message using encryption key 'ekey', working modulo n. message: The integer message to encrypt, ekey: The RSA encryption key, n: The modulus for RSA encryption. Example: encrypt_integer(123, 5, 1000) -> 827"""
    from rsa.core import encrypt_int

    try:
        return encrypt_int(message, ekey, n)
    except AssertionError as e:
        raise ValueError("Invalid input parameters") from e
    except ValueError as e:
        raise ValueError(str(e)) from e
    except OverflowError as e:
        raise OverflowError(str(e)) from e

def decrypt_integer(cyphertext: int, dkey: int, n: int) -> int:
    """Decrypts a cypher text using the decryption key 'dkey', working modulo n. cyphertext: The encrypted integer to decrypt, dkey: The RSA private decryption exponent, n: The RSA modulus, e.g. decrypt_integer(123, 456, 789) -> 678."""
    try:
        return pow(cyphertext, dkey, n)
    except TypeError:
        raise ValueError("All parameters must be integers")

from rsa.randnum import read_random_int


def read_random_integer(nbits: int) -> int:
    """Reads a random integer of approximately nbits bits. nbits: The approximate number of bits for the random integer, e.g. read_random_integer(8) -> 173."""
    if nbits <= 0:
        raise ValueError("nbits must be positive")

    try:
        return read_random_int(nbits)
    except Exception as e:
        raise ValueError(f"failed to read random integer: {str(e)}")
